package com.bank.growth;

import com.bank.growth.model.CareerPlan;
import com.bank.growth.service.GrowthProjector;
import java.util.List;
import java.util.logging.*;

// Runnable demo: project a 3-5 year career plan like a bank projects portfolio growth.
public class GrowthDemo {
    private static final Logger log = Logger.getLogger("Growth");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        GrowthProjector projector = new GrowthProjector(log);

        // Weak plan — a title with no capabilities, and an exit intent.
        CareerPlan weak = new CareerPlan(
            "Senior Engineer", "Engineering Manager",
            List.of(),                       // no capabilities named
            true);                           // plans to leave (startup)
        projector.project(weak);

        // Strong plan — capability-driven growth that stays in the company.
        CareerPlan strong = new CareerPlan(
            "Senior Engineer", "Staff Engineer (fraud architecture)",
            List.of("Own fraud platform design",
                    "Lead design reviews",
                    "Mentor two junior engineers"),
            false);                          // committed to the company
        projector.project(strong);
    }
}
