package com.bank.growth.model;

import java.util.List;

// Models a 5-year plan: where you are, where you aim, and the capabilities in between.
public class CareerPlan {
    private final String currentLevel;
    private final String targetLevel;
    private final List<String> capabilities;   // the PATH, not just the title
    private final boolean plansToLeave;

    public CareerPlan(String currentLevel, String targetLevel,
                      List<String> capabilities, boolean plansToLeave) {
        this.currentLevel = currentLevel;
        this.targetLevel = targetLevel;
        this.capabilities = capabilities;
        this.plansToLeave = plansToLeave;
    }

    public String getCurrentLevel() { return currentLevel; }
    public String getTargetLevel() { return targetLevel; }
    public List<String> getCapabilities() { return capabilities; }
    public boolean plansToLeave() { return plansToLeave; }

    // A fundable plan has a concrete path of capabilities to build.
    public boolean hasRealisticPath() {
        return capabilities != null && !capabilities.isEmpty();
    }
}
