package com.bank.growth.service;

import com.bank.growth.model.CareerPlan;
import java.util.logging.*;

// Validates a career plan the way a bank validates whether a growth goal is fundable.
public class GrowthProjector {
    private final Logger log;

    public GrowthProjector(Logger log) { this.log = log; }

    public void project(CareerPlan plan) {
        if (plan.plansToLeave()) {
            // An exit plan is like a customer about to withdraw everything.
            log.warning(() -> "EXIT intent detected — keep the ambition inside the company.");
            return;
        }
        if (!plan.hasRealisticPath()) {
            log.warning(() -> "Target \"" + plan.getTargetLevel()
                + "\" has no path — name the capabilities you will build.");
            return;
        }
        log.info(() -> "FUNDABLE plan: " + plan.getCurrentLevel()
            + " to " + plan.getTargetLevel() + " via " + plan.getCapabilities());
        plan.getCapabilities().forEach(c -> log.fine(() -> "   building capability: " + c));
    }
}
